<script setup>
import {computed,ref} from 'vue'
import {focusControl} from '../../shared/focusControl.js'
import OptionPicker from '../../shared/components/OptionPicker.vue'
import {toast} from '../../shared/composables/toast.js'
import {Badge,Button,Checkbox,Field,FieldLabel,Input,Spinner,Table,TableBody,TableCell,TableHead,TableHeader,TableRow} from '../../shared/shadcn-ui.js'
const props=defineProps({service:String,environments:Array,connections:Array,request:Function,disabled:Boolean})
const emit=defineEmits(['apply','busy'])
const scope=ref([]),nacos=ref({}),profiles=ref({}),path=ref(''),bootstrap=ref(''),pom=ref(''),busy=ref(false),result=ref(null),selected=ref([])
const runtimeName=ref(''),sourceName=ref(''),sourceFormat=ref('yaml'),adapter=ref('spring'),job=ref(''),configDataID=ref(''),configGroup=ref(''),runtimeInput=ref(null)
const inputKey=computed(()=>JSON.stringify([props.service,scope.value,nacos.value,profiles.value,path.value,bootstrap.value,pom.value,runtimeName.value,sourceName.value,sourceFormat.value,adapter.value,job.value,configDataID.value,configGroup.value]))
const resultKey=ref(''),resultCurrent=computed(()=>resultKey.value===inputKey.value)
async function readSource(event,field){const file=event.target.files?.[0];if(!file)return;if(file.size>512*1024){toast('源文件不能超过 512 KiB','warning');return}const text=await file.text();if(field==='bootstrap'){bootstrap.value=text;sourceName.value=file.name;sourceFormat.value=file.name.endsWith('.properties')?'properties':'yaml'}else pom.value=text;result.value=null;selected.value=[]}
async function discover(){
 if(busy.value||!scope.value.length)return
 busy.value=true;emit('busy',true);selected.value=[];result.value=null
 try{const key=inputKey.value;result.value=await props.request(`api/services/${encodeURIComponent(props.service)}/resources/discover`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({environments:scope.value,connections:nacos.value,profiles:profiles.value,bootstrap_path:path.value,bootstrap_content:bootstrap.value,pom_content:pom.value,runtime_name:runtimeName.value,source_name:sourceName.value,source_format:bootstrap.value?sourceFormat.value:path.value.endsWith('.properties')?'properties':'yaml',adapter:adapter.value,job:job.value,config_data_id:configDataID.value,config_group:configGroup.value})});resultKey.value=key;toast('识别完成，请选择候选并核对差异；尚未保存','success')}
 catch(e){toast(e.message,'error');if(/运行名/.test(e.message))focusControl(runtimeInput.value)}finally{busy.value=false;emit('busy',false)}
}
function choose(item,value){selected.value=value===true?[...new Set([...selected.value,item.id])]:selected.value.filter(id=>id!==item.id)}
function apply(){if(resultCurrent.value&&!busy.value&&!props.disabled)emit('apply',result.value.items.filter(item=>selected.value.includes(item.id)))}
</script>
<template>
 <section class="min-w-0 space-y-4" aria-label="代码与 Nacos 依赖识别">
  <div class="grid gap-3 sm:grid-cols-2"><Field><FieldLabel>识别环境</FieldLabel><OptionPicker v-model="scope" multiple :options="(environments||[]).map(e=>({value:e.name,label:e.display_name||e.name}))" placeholder="显式选择环境" aria-label="依赖识别环境" :disabled="disabled||busy"/></Field><Field><FieldLabel>bootstrap 相对路径（可选）</FieldLabel><Input v-model="path" placeholder="留空匹配已拉取源码中的当前应用" :disabled="disabled||busy"/></Field></div>
  <div class="grid gap-3 sm:grid-cols-2"><Field><FieldLabel>Spring运行名（与平台ID不同时填写）</FieldLabel><Input ref="runtimeInput" v-model="runtimeName" aria-label="依赖运行名" placeholder="例如 bus-job；不会修改平台应用ID" :disabled="disabled||busy"/></Field><Field><FieldLabel>配置结构</FieldLabel><OptionPicker v-model="adapter" :options="[{value:'spring',label:'Spring Boot 环境配置'},{value:'custom',label:'固定Data ID / 数据智能'},{value:'flink',label:'Flink common + jobs'}]" aria-label="依赖配置结构" :disabled="disabled||busy"/></Field></div>
  <div v-if="adapter!=='spring'" class="grid gap-3 sm:grid-cols-2"><Field><FieldLabel>固定Data ID</FieldLabel><Input v-model="configDataID" aria-label="识别固定Data ID" :disabled="disabled||busy"/></Field><Field><FieldLabel>Group</FieldLabel><Input v-model="configGroup" aria-label="识别配置Group" :disabled="disabled||busy"/></Field><Field v-if="adapter==='flink'"><FieldLabel>本次Flink作业</FieldLabel><OptionPicker v-if="result?.jobs?.length" v-model="job" :options="result.jobs.map(value=>({value,label:value}))" placeholder="选择一个作业后重新识别" aria-label="识别Flink作业" :disabled="disabled||busy"/><Input v-else v-model="job" placeholder="可先留空读取作业列表" aria-label="识别Flink作业" :disabled="disabled||busy"/></Field></div>
  <div v-for="environment in scope" :key="environment" class="grid items-center gap-2 sm:grid-cols-[100px_minmax(0,1fr)_160px]"><span class="text-sm">{{environments.find(e=>e.name===environment)?.display_name||environment}}</span><OptionPicker v-model="nacos[environment]" :options="(connections||[]).filter(c=>c.kind==='nacos').map(c=>({value:c.name,label:c.name+' · '+(c.config?.namespace||'public')}))" all-label="仅在来源可唯一确认时匹配连接" :disabled="disabled||busy" :aria-label="environment+' 识别 Nacos 连接'"/><Input v-model="profiles[environment]" :placeholder="'profile 默认 '+environment" :aria-label="environment+' 源码 profile'" :disabled="disabled||busy"/></div>
  <div class="grid gap-3 sm:grid-cols-2"><Field><FieldLabel>或上传 bootstrap / application / properties</FieldLabel><Input type="file" accept=".yml,.yaml,.properties" :disabled="disabled||busy" @change="event=>readSource(event,'bootstrap')"/></Field><Field><FieldLabel>pom.xml（解析环境参数，可选）</FieldLabel><Input type="file" accept=".xml" :disabled="disabled||busy" @change="event=>readSource(event,'pom')"/></Field></div>
  <div class="flex flex-wrap items-center gap-2"><Button variant="outline" :disabled="disabled||busy||!scope.length" @click="discover"><Spinner v-if="busy"/>识别依赖</Button><span class="text-xs text-muted-foreground">只读取源码和所选配置，不构建、不发布；候选中不返回密码</span></div>
  <template v-if="result"><p v-if="!resultCurrent" role="status" class="text-xs text-muted-foreground">识别条件已变化，请重新识别后加入草稿。</p><p class="break-all text-xs text-muted-foreground">来源：{{result.source}} · 运行名 {{result.origin?.runtime_name||service}} · {{result.items?.length||0}} 项候选</p><p v-if="result.origin?.artifact" class="break-all text-xs text-muted-foreground">配置产物：{{result.origin.artifact}} · 源文件摘要：{{result.source_digest}}</p><div class="max-h-[42dvh] overflow-auto rounded-lg border"><Table class="table-fixed min-w-[650px]"><TableHeader><TableRow><TableHead class="w-12">选择</TableHead><TableHead class="w-28">环境</TableHead><TableHead class="w-40">资源</TableHead><TableHead>目标与状态</TableHead></TableRow></TableHeader><TableBody><TableRow v-for="item in result.items" :key="item.id"><TableCell><Checkbox :model-value="selected.includes(item.id)" :disabled="!resultCurrent||(!item.applyable&&!item.can_declare)||busy||disabled" :aria-label="'候选 '+item.environment+' '+item.alias" @update:model-value="value=>choose(item,value)"/></TableCell><TableCell>{{item.environment}}</TableCell><TableCell class="whitespace-normal break-all">{{item.alias}}<small v-if="item.original_alias&amp;&amp;item.original_alias!==item.alias" class="block text-muted-foreground">源名：{{item.original_alias}}</small><Badge variant="secondary">{{item.kind}}</Badge></TableCell><TableCell class="whitespace-normal break-all"><p>{{item.connection||item.endpoint||'需核对连接'}}{{item.database?' / '+item.database:''}}{{item.data_id?' / '+item.group+' / '+item.data_id:''}}</p><p v-if="!item.applyable&amp;&amp;item.can_declare" class="text-xs font-medium">仅登记声明，目标待完善</p><p class="text-xs text-muted-foreground">{{item.message||(item.applyable?'可加入草稿，目标尚需核验':'需单独配置')}}</p></TableCell></TableRow></TableBody></Table></div><ul class="space-y-1 text-xs text-muted-foreground"><li v-for="warning in result.warnings" :key="warning">{{warning}}</li></ul><Button :disabled="disabled||busy||!resultCurrent||!selected.length" @click="apply">加入草稿 · {{selected.length}} 项</Button></template>
 </section>
</template>
